package net.civeira.phylax.features.oauth.tokensecurity.infrastructure.driver;

import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Base64;

import org.jose4j.jwt.JwtClaims;
import org.jose4j.jwt.MalformedClaimException;
import org.jose4j.jwt.NumericDate;
import org.jose4j.jwt.consumer.InvalidJwtException;

import io.smallrye.jwt.auth.principal.DefaultJWTCallerPrincipal;
import io.smallrye.jwt.auth.principal.JWTAuthContextInfo;
import io.smallrye.jwt.auth.principal.JWTCallerPrincipal;
import io.smallrye.jwt.auth.principal.JWTCallerPrincipalFactory;
import io.smallrye.jwt.auth.principal.ParseException;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import jakarta.json.Json;
import jakarta.json.JsonObject;
import lombok.Builder;
import lombok.Data;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenSigner;

/**
 * JWT caller principal factory that validates signatures with TokenSigner.
 *
 * Responsibilities: - Parse JWTs into SmallRye JWT principals. - Verify token signatures using
 * configured keys.
 *
 * Design notes: - Uses TokenSigner for keypass validation. - Provides minimal caching via Cacheable
 * wrapper.
 */
@ApplicationScoped
@Alternative
@Priority(1)
@Slf4j
public class TokenJwtCallerPrincipalFactory extends JWTCallerPrincipalFactory {
  @Data
  @RequiredArgsConstructor
  /**
   * Parsed JWT components used during validation.
   */
  private static class ParsedToken {
    /**
     * JWT header as JSON.
     */
    private final JsonObject header;
    /**
     * JWT claims payload.
     */
    private final JwtClaims claims;
    /**
     * Principal created from the claims.
     */
    private final JWTCallerPrincipal principal;
  }

  /**
   * Cacheable wrapper for validated principals.
   *
   * Holds successful principals or failure details. Used to avoid repeated parsing in a short
   * window.
   */
  @Data
  @Builder
  private static class Cacheable {
    /**
     * Error message for failed parsing or validation.
     */
    private final String error;
    /**
     * Exception raised during parsing or validation.
     */
    private final Throwable exception;
    /**
     * Cached principal when validation succeeds.
     */
    private final JWTCallerPrincipal principal;
    /**
     * Cache expiration timestamp in milliseconds.
     */
    private final long until;

    /**
     * Creates a successful cache entry.
     *
     * Stores the principal until the provided expiration instant. Used after signature validation
     * succeeds.
     *
     * @param principal validated principal
     * @param instant expiration instant
     * @return cacheable success entry
     */
    public static Cacheable ok(JWTCallerPrincipal principal, Instant instant) {
      return Cacheable.builder().principal(principal).until(instant.toEpochMilli()).build();
    }

    /**
     * Creates a failed cache entry with an error message.
     *
     * Used when parsing or validation fails without exception. Does not include an exception
     * reference.
     *
     * @param error error message
     * @return cacheable failure entry
     */
    public static Cacheable fail(String error) {
      return Cacheable.builder().error(error).build();
    }

    /**
     * Creates a failed cache entry with an error and exception.
     *
     * Used when parsing or validation throws an exception. Stores the exception for diagnostics.
     *
     * @param error error message
     * @param th exception instance
     * @return cacheable failure entry
     */
    public static Cacheable fail(String error, Throwable th) {
      return Cacheable.builder().error(error).exception(th).build();
    }

    /**
     * Returns the cached principal or throws a parse exception.
     *
     * Validates expiration and returns the principal if still valid. Throws ParseException for
     * expired or invalid entries.
     *
     * @return JWT caller principal
     * @throws ParseException when token is expired or invalid
     */
    JWTCallerPrincipal principalLoaded() throws ParseException {
      if (null != principal && until > Instant.now().toEpochMilli()) {
        return principal;
      } else if (null != principal) {
        throw new ParseException("Expired token");
      } else {
        throw new ParseException(error, getException());
      }
    }
  }

  /**
   * Token signer used to validate keypass signatures.
   */
  private final TokenSigner tokenSigner;

  /**
   * Creates the factory with the required token signer.
   *
   * Injects TokenSigner to validate JWT keypass signatures. Calls the super constructor with
   * default settings.
   *
   * @param tokenSigner token signer implementation
   */
  public TokenJwtCallerPrincipalFactory(TokenSigner tokenSigner) {
    super();
    this.tokenSigner = tokenSigner;
  }

  /**
   * Parses and validates the JWT token.
   *
   * Throws when the token is empty or invalid. Delegates validation to TokenSigner.
   *
   * @param token raw JWT token
   * @param authContextInfo auth context info
   * @return JWT caller principal
   * @throws ParseException when parsing or validation fails
   */
  @Override
  public JWTCallerPrincipal parse(String token, JWTAuthContextInfo authContextInfo)
      throws ParseException {
    if (token == null || token.isBlank()) {
      throw new ParseException("Empty token", null);
    }
    return this.caller(token).principalLoaded();
  }

  /**
   * Builds a cacheable validation result for a token.
   *
   * Parses header and claims, then validates signature. Returns a Cacheable with principal or
   * failure details.
   *
   * @param token raw JWT token
   * @return cacheable result
   */
  private Cacheable caller(String token) {
    ParsedToken parsed;
    try {
      parsed = parseHeaderAndClaims(token);
    } catch (ParseException e) {
      return Cacheable.fail("Unable to parse token", e);
    }
    try {
      String tenant = resolveTenant(parsed.getClaims());
      String issuer = safeIssuer(parsed.getClaims());
      String tid = safeClaim(parsed.getClaims(), "tid");
      String keypass = tokenSigner.verifiedKeypass(tenant, token);
      if (null == keypass || keypass.isBlank()) {
        log.warn(
            "jwt principal verification failed: invalid sign tenantResolved={} iss={} tid={} kid={}",
            tenant, issuer, tid, parsed.getHeader().getString("kid", ""));
        return Cacheable.fail("Invalid JWT sign");
      }
      Instant expiresAt = expirationFromClaims(parsed.getClaims());
      log.debug("jwt principal verified: tenantResolved={} iss={} tid={} kid={}", tenant, issuer,
          tid, parsed.getHeader().getString("kid", ""));
      return Cacheable.ok(parsed.getPrincipal(), expiresAt);
    } catch (RuntimeException e) {
      log.error("jwt principal verification error: {}", e.getMessage(), e);
      return Cacheable.fail("Unable to load the keys", e);
    }
  }

  /**
   * Extracts the expiration instant from JWT claims.
   *
   * Returns the current time when expiration is missing or invalid. Protects against malformed
   * claim values.
   *
   * @param claims JWT claims
   * @return expiration instant
   */
  private Instant expirationFromClaims(JwtClaims claims) {
    try {
      NumericDate expiration = claims.getExpirationTime();
      if (null != expiration) {
        return Instant.ofEpochSecond((long) expiration.getValue());
      }
    } catch (RuntimeException | MalformedClaimException ex) {
      return Instant.now();
    }
    return Instant.now();
  }

  private String resolveTenant(JwtClaims claims) {
    try {
      String issuer = claims.getIssuer();
      if (issuer != null) {
        int idx = issuer.lastIndexOf("/oauth/openid/");
        if (idx >= 0) {
          String tenant = issuer.substring(idx + "/oauth/openid/".length());
          if (!tenant.isBlank()) {
            return tenant;
          }
        }
      }
    } catch (MalformedClaimException ignored) {
      // fallback to tid
    }
    try {
      String tid = claims.getStringClaimValue("tid");
      if (tid != null && !tid.isBlank()) {
        return tid;
      }
    } catch (MalformedClaimException ignored) {
      // no-op
    }
    return "";
  }

  private String safeIssuer(JwtClaims claims) {
    try {
      return claims.getIssuer();
    } catch (MalformedClaimException ex) {
      return "";
    }
  }

  private String safeClaim(JwtClaims claims, String claim) {
    try {
      String value = claims.getStringClaimValue(claim);
      return value == null ? "" : value;
    } catch (MalformedClaimException ex) {
      return "";
    }
  }

  /**
   * Parses JWT header and claims without verifying signature.
   *
   * Validates token format and builds a SmallRye principal. Throws ParseException when decoding
   * fails.
   *
   * @param token raw JWT token
   * @return parsed token components
   * @throws ParseException when parsing fails
   */
  private static ParsedToken parseHeaderAndClaims(String token) throws ParseException {
    try {
      String[] parts = token.split("\\.");
      if (parts.length != 3) {
        throw new ParseException("Invalid JWT format, expected 3 parts but got " + parts.length);
      }

      // 1) HEADER
      String headerJson =
          new String(Base64.getUrlDecoder().decode(parts[0]), StandardCharsets.UTF_8);
      JsonObject header = Json.createReader(new StringReader(headerJson)).readObject();

      // 2) PAYLOAD / CLAIMS
      String claimsJson =
          new String(Base64.getUrlDecoder().decode(parts[1]), StandardCharsets.UTF_8);
      JwtClaims claims = JwtClaims.parse(claimsJson);

      // 3) PRINCIPAL (SmallRye)
      JWTCallerPrincipal principal = new DefaultJWTCallerPrincipal(claims);

      return new ParsedToken(header, claims, principal);
    } catch (InvalidJwtException e) {
      throw new ParseException(e.getMessage(), e);
    } catch (IllegalArgumentException e) {
      throw new ParseException("Error decoding JWT: " + e.getMessage(), e);
    }
  }
}
